// Des: One JSON document per answer, failures too
// Flo: captured stdout > one object gets ok, cmd, exit > other text goes in lines > failure doc carries code and msg
// I/O: command word + exit code + captured text (caller) > one JSON document (arena owned)
// ===================================================================
const std = @import("std");
fn qute(allo: std.mem.Allocator, text: []const u8) ![]const u8 { return std.json.Stringify.valueAlloc(allo, text, .{}); }
pub fn snakName(allo: std.mem.Allocator, name: []const u8) ![]const u8 { var outp: std.ArrayList(u8) = .empty; for (name, 0..) |chrz, indx| { if (std.ascii.isUpper(chrz)) { if (indx > 0) try outp.append(allo, '_'); try outp.append(allo, std.ascii.toLower(chrz)); } else try outp.append(allo, chrz); } return outp.items; }
fn headKeys(allo: std.mem.Allocator, cmdz: []const u8, code: u8, dryz: ?bool, have: ?std.json.ObjectMap) ![]const u8 { var outp: std.ArrayList(u8) = .empty; const cmdq = try qute(allo, cmdz); if (have == null or !have.?.contains("ok")) try outp.appendSlice(allo, try std.fmt.allocPrint(allo, "\"ok\":{s},", .{if (code == 0) "true" else "false"})); if (have == null or !have.?.contains("cmd")) try outp.appendSlice(allo, try std.fmt.allocPrint(allo, "\"cmd\":{s},", .{cmdq})); if (have == null or !have.?.contains("exit")) try outp.appendSlice(allo, try std.fmt.allocPrint(allo, "\"exit\":{d},", .{code})); if (dryz) |dryv| { if (have == null or !have.?.contains("dry_run")) try outp.appendSlice(allo, try std.fmt.allocPrint(allo, "\"dry_run\":{s},", .{if (dryv) "true" else "false"})); } return outp.items; }
pub fn okayDoc(allo: std.mem.Allocator, cmdz: []const u8, code: u8, rawz: []const u8, dryz: ?bool) ![]const u8 { const trim = std.mem.trim(u8, rawz, " \t\r\n"); if (trim.len > 1 and trim[0] == '{') { if (std.json.parseFromSliceLeaky(std.json.Value, allo, trim, .{})) |valu| { if (valu == .object) { const head = try headKeys(allo, cmdz, code, dryz, valu.object); const rest = std.mem.trim(u8, trim[1..], " \t\r\n"); if (rest.len == 1) return std.fmt.allocPrint(allo, "{{{s}}}", .{std.mem.trimEnd(u8, head, ",")}); return std.fmt.allocPrint(allo, "{{{s}{s}", .{ head, rest }); } } else |_| {} }
const head = try headKeys(allo, cmdz, code, dryz, null); if (trim.len > 1 and trim[0] == '[') { if (std.json.parseFromSliceLeaky(std.json.Value, allo, trim, .{})) |valu| { if (valu == .array) return std.fmt.allocPrint(allo, "{{{s}\"data\":{s}}}", .{ head, trim }); } else |_| {} } if (trim.len == 0) return std.fmt.allocPrint(allo, "{{{s}}}", .{std.mem.trimEnd(u8, head, ",")}); var lins: std.ArrayList(u8) = .empty; var iter = std.mem.splitScalar(u8, trim, '\n'); var firs = true; while (iter.next()) |item| { const line = std.mem.trim(u8, item, " \t\r"); if (line.len == 0) continue; if (!firs) try lins.append(allo, ','); firs = false; try lins.appendSlice(allo, try qute(allo, line)); } return std.fmt.allocPrint(allo, "{{{s}\"lines\":[{s}]}}", .{ head, lins.items }); }
pub fn failDoc(allo: std.mem.Allocator, cmdz: []const u8, code: u8, name: []const u8, msgz: []const u8, dryz: ?bool) ![]const u8 { const head = try headKeys(allo, cmdz, code, dryz, null); return std.fmt.allocPrint(allo, "{{{s}\"code\":{s},\"msg\":{s}}}", .{ head, try qute(allo, try snakName(allo, name)), try qute(allo, msgz) }); }
